import{_ as t,o as a,c as n,a4 as e}from"./chunks/framework.BMj-uaUw.js";const g=JSON.parse('{"title":"单元 6 · AI 协作：表单校验要写全，副作用要清干净","description":"","frontmatter":{},"headers":[{"level":2,"title":"这一章哪些活能交给 AI","slug":"这一章哪些活能交给-ai","link":"#这一章哪些活能交给-ai","children":[]},{"level":2,"title":"提示词怎么写","slug":"提示词怎么写","link":"#提示词怎么写","children":[{"level":3,"title":"1. 让它写一组校验规则","slug":"_1-让它写一组校验规则","link":"#_1-让它写一组校验规则","children":[]},{"level":3,"title":"2. 让它检查副作用有没有清干净","slug":"_2-让它检查副作用有没有清干净","link":"#_2-让它检查副作用有没有清干净","children":[]},{"level":3,"title":"3. 让它解释事件与修饰符的触发时机","slug":"_3-让它解释事件与修饰符的触发时机","link":"#_3-让它解释事件与修饰符的触发时机","children":[]}]},{"level":2,"title":"AI 在这一章容易错什么","slug":"ai-在这一章容易错什么","link":"#ai-在这一章容易错什么","children":[{"level":3,"title":"把 v-model 修饰符讲成“只是个小优化”","slug":"把-v-model-修饰符讲成-只是个小优化","link":"#把-v-model-修饰符讲成-只是个小优化","children":[]},{"level":3,"title":"input 与 change 的触发时机说反","slug":"input-与-change-的触发时机说反","link":"#input-与-change-的触发时机说反","children":[]},{"level":3,"title":"只做了前端校验就宣称“安全了”","slug":"只做了前端校验就宣称-安全了","link":"#只做了前端校验就宣称-安全了","children":[]},{"level":3,"title":"忘记清理副作用","slug":"忘记清理副作用","link":"#忘记清理副作用","children":[]}]},{"level":2,"title":"怎么验收 AI 的产出","slug":"怎么验收-ai-的产出","link":"#怎么验收-ai-的产出","children":[]},{"level":2,"title":"练习","slug":"练习","link":"#练习","children":[{"level":3,"title":"给一个带实时校验的表单，故意留一个没清理的定时器","slug":"给一个带实时校验的表单-故意留一个没清理的定时器","link":"#给一个带实时校验的表单-故意留一个没清理的定时器","children":[]}]}],"relativePath":"unit06/ai-collaboration.md","filePath":"unit06/ai-collaboration.md","lastUpdated":1789356894000}'),i={name:"unit06/ai-collaboration.md"};function l(d,s,p,o,r,h){return a(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="单元-6-·-ai-协作-表单校验要写全-副作用要清干净" tabindex="-1">单元 6 · AI 协作：表单校验要写全，副作用要清干净 <a class="header-anchor" href="#单元-6-·-ai-协作-表单校验要写全-副作用要清干净" aria-label="Permalink to &quot;单元 6 · AI 协作：表单校验要写全，副作用要清干净&quot;">​</a></h1><p>表单是 bug 最集中的地方，这一章的知识点也最密：事件、修饰符、表单绑定、校验、生命周期清理。AI 在这一章的产出量会明显变大 —— 它能帮你把校验规则、错误文案、防重复提交这些东西一次写出来。</p><p>但它有一个固定的偏差：<strong>它写的表单通常只有“顺利填完并提交成功”这一条路径。</strong> 校验失败的提示、重复点击的保护、组件卸载时的清理，这三样它经常漏。</p><p>这一章讲的是<strong>怎么让它把“不顺利的那几条路径”也写出来，以及怎么检查它有没有清干净副作用。</strong></p><h2 id="这一章哪些活能交给-ai" tabindex="-1">这一章哪些活能交给 AI <a class="header-anchor" href="#这一章哪些活能交给-ai" aria-label="Permalink to &quot;这一章哪些活能交给 AI&quot;">​</a></h2><p>判断标准：<strong>机械规则和清单式检查可以交；涉及“这条规则该由谁管”的判断不能交。</strong></p><table tabindex="0"><thead><tr><th>任务</th><th>能交给 AI 吗</th><th>为什么</th></tr></thead><tbody><tr><td>起草一组校验规则（纯函数形式）</td><td>可以</td><td>规则本身是机械的，写完你逐条对业务</td></tr><tr><td>生成错误提示文案</td><td>可以</td><td>一句话的事，你挑一条改改就行</td></tr><tr><td>检查副作用有没有清理干净</td><td>可以</td><td>它对着钩子清单比人快</td></tr><tr><td>解释事件与修饰符的触发时机</td><td>可以</td><td>但要它给能观察到的例子</td></tr><tr><td>设计防重复提交的分层防护</td><td>可以</td><td>当起点，层次要你确认</td></tr><tr><td>判断“这条规则该不该由前端来管”</td><td><strong>不能直接信</strong></td><td>它容易把前端校验说成够用了</td></tr><tr><td>判断“校验做完了就安全了吗”</td><td><strong>不能直接信</strong></td><td>见下面“容易错什么”第三条</td></tr><tr><td>决定校验失败时的交互方式</td><td><strong>不行</strong></td><td>取决于用户习惯，也和你们组的约定有关</td></tr></tbody></table><p>中间那两行合起来是一件事：<strong>前端校验挡的是手误，不挡恶意请求。</strong> 这句话 AI 不一定说错，但它默认不提，你不问它就不讲。</p><h2 id="提示词怎么写" tabindex="-1">提示词怎么写 <a class="header-anchor" href="#提示词怎么写" aria-label="Permalink to &quot;提示词怎么写&quot;">​</a></h2><h3 id="_1-让它写一组校验规则" tabindex="-1">1. 让它写一组校验规则 <a class="header-anchor" href="#_1-让它写一组校验规则" aria-label="Permalink to &quot;1. 让它写一组校验规则&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要给“创建活动”表单写校验，字段有：活动名称、报名开始时间、</span></span>
<span class="line"><span>报名截止时间、名额上限。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>项目约定：校验规则写成一组纯函数，放 src/domain/ 下，</span></span>
<span class="line"><span>每个函数接收值（需要多个字段时接收整个表单对象），</span></span>
<span class="line"><span>返回错误信息字符串或空字符串。不依赖 Vue。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请按这个约定写。要求：</span></span>
<span class="line"><span>1. 每个规则单独一个函数，函数名说清它检查什么</span></span>
<span class="line"><span>2. 时间类规则注意这两个：截止时间必须晚于开始时间；</span></span>
<span class="line"><span>   报名开始时间不能早于当前时间</span></span>
<span class="line"><span>3. 名额上限要求是 1 到 500 之间的整数</span></span>
<span class="line"><span>4. 每写完一条，说明“什么情况下它会误判”（合法输入被判为非法）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果你发现有哪条规则必须查后端才能判断，单独列出来，不要硬写成同步规则。</span></span></code></pre></div><p><strong>为什么这么写</strong>：第 4 点是最有价值的一句。<strong>校验规则最容易出的问题不是漏判，是误判</strong> —— 比如“报名开始时间不能早于当前时间”这条，如果用户现在就在填，时间秒级对不上就会误判。让它自己说出误判场景，比你自己想全要省力。</p><p>最后一句也很关键：有些规则（比如“名额不能超过场地容量”）必须查后端，硬写成同步规则会让代码结构扭曲。让它主动标出来，你才知道哪些该放到异步校验里。</p><h3 id="_2-让它检查副作用有没有清干净" tabindex="-1">2. 让它检查副作用有没有清干净 <a class="header-anchor" href="#_2-让它检查副作用有没有清干净" aria-label="Permalink to &quot;2. 让它检查副作用有没有清干净&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是我的组件：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[粘贴完整代码]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请做一件事：把代码里所有的副作用列出来，逐个说明它在哪里被清理、清理得对不对。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>副作用包括但不限于：定时器、事件监听（window、document、元素）、</span></span>
<span class="line"><span>请求、订阅、手动创建的 DOM 节点。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出用表格，四列：</span></span>
<span class="line"><span>副作用 / 在哪注册的 / 在哪清理的 / 有没有问题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>没问题就写“无”，不要为了显得认真而硬找问题。</span></span></code></pre></div><p><strong>为什么这么写</strong>：把“检查一下”拆成“列出来 → 逐个落到清理位置”，它就必须对着代码逐行核对，而不是回一句“整体看起来规范”。表格里“在哪清理的”这一列是核心 —— 这一列空着的，就是漏掉的。</p><p>最后那句“不要硬找问题”是必要的。这类检查请求太宽泛时，它会为了显得有用而编几条问题，反而增加你的核对成本。</p><h3 id="_3-让它解释事件与修饰符的触发时机" tabindex="-1">3. 让它解释事件与修饰符的触发时机 <a class="header-anchor" href="#_3-让它解释事件与修饰符的触发时机" aria-label="Permalink to &quot;3. 让它解释事件与修饰符的触发时机&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请解释这几个东西的触发时机差别，每个都用一个“在浏览器里能观察到”的例子说明：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. input 事件与 change 事件</span></span>
<span class="line"><span>2. v-model 与 v-model.lazy</span></span>
<span class="line"><span>3. .stop 与 .self</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：每个例子写清“做什么操作 → 控制台会输出什么”，</span></span>
<span class="line"><span>我要能照着做一遍验证。不要只讲定义。</span></span></code></pre></div><p><strong>为什么这么写</strong>：触发时机这类知识，定义背下来没用，必须在真实操作里对上号。要求它给“做什么操作 → 看到什么”，你就有了三个能亲手验证的小实验。这三个里 <code>.stop</code> 与 <code>.self</code> 最容易混 —— 差别在于拦的是“所有冒泡上来的事件”还是“只拦目标是自己触发的那些”。</p><h2 id="ai-在这一章容易错什么" tabindex="-1">AI 在这一章容易错什么 <a class="header-anchor" href="#ai-在这一章容易错什么" aria-label="Permalink to &quot;AI 在这一章容易错什么&quot;">​</a></h2><h3 id="把-v-model-修饰符讲成-只是个小优化" tabindex="-1">把 <code>v-model</code> 修饰符讲成“只是个小优化” <a class="header-anchor" href="#把-v-model-修饰符讲成-只是个小优化" aria-label="Permalink to &quot;把 \`v-model\` 修饰符讲成“只是个小优化”&quot;">​</a></h3><p><strong>现象</strong>：它介绍 <code>.lazy</code> 时说“减少触发次数，性能更好”，介绍 <code>.number</code> 时说“自动转成数字”。你要是只按这两句话理解，会写出有问题的代码。</p><p><strong>原因</strong>：这类“修饰符是什么”的解释，在各类教程里都停在这个层次，它照着这个层次讲，不会主动补边界。</p><p><strong>怎么处理</strong>：两个修饰符各记一条边界。</p><p><code>.lazy</code> 改的是<strong>数据更新的时机</strong>，不是触发频率：</p><table tabindex="0"><thead><tr><th>你可能以为</th><th>实际上</th></tr></thead><tbody><tr><td>值照样实时更新，只是少了些事件</td><td>输入过程中值<strong>根本不变</strong>，失焦才更新</td></tr></tbody></table><p>后果：别处依赖这个值做实时预览的地方，加上 <code>.lazy</code> 之后会“卡住不动”，直到输入框失焦。所以<strong>不要为了省请求随手加它</strong>。</p><p><code>.number</code> 转不了会<strong>保留原字符串</strong>，而且它内部的转换逻辑是“能读多少读多少”：</p><table tabindex="0"><thead><tr><th>用户输入</th><th><code>v-model.number</code> 得到的值</th></tr></thead><tbody><tr><td><code>50</code></td><td>数字 <code>50</code></td></tr><tr><td>空字符串</td><td>字符串 <code>&#39;&#39;</code></td></tr><tr><td><code>abc</code></td><td>字符串 <code>&#39;abc&#39;</code></td></tr><tr><td><code>12abc</code></td><td>数字 <code>12</code></td></tr></tbody></table><p>最后一行最危险：输入 <code>12abc</code> 拿到数字 <code>12</code>，<strong>“格式不对”这件事被悄悄吞掉了</strong>。所以<strong>校验不能只看类型，必须校验值本身</strong>。这一条在<a href="/frontend-engineering-course/unit06/04-validation.html">6.4 表单校验</a>里有完整处理。</p><h3 id="input-与-change-的触发时机说反" tabindex="-1"><code>input</code> 与 <code>change</code> 的触发时机说反 <a class="header-anchor" href="#input-与-change-的触发时机说反" aria-label="Permalink to &quot;\`input\` 与 \`change\` 的触发时机说反&quot;">​</a></h3><p><strong>现象</strong>：它说“<code>change</code> 在输入时触发，<code>input</code> 在失焦时触发”，或者把两者说成一回事。</p><p><strong>原因</strong>：这两个事件名起得不直观 —— <code>input</code>（输入）听起来像“输入完成”，实际是“每敲一次”；<code>change</code>（改变）听起来像每次变化，实际是“值定了而且变了”。</p><p><strong>怎么处理</strong>：用一组操作把它对上号。</p><table tabindex="0"><thead><tr><th>操作</th><th><code>input</code></th><th><code>change</code></th></tr></thead><tbody><tr><td>敲第一个字符</td><td>触发</td><td>不触发</td></tr><tr><td>继续敲</td><td>每敲一次都触发</td><td>不触发</td></tr><tr><td>失焦</td><td>不触发</td><td>触发（值变过才触发）</td></tr><tr><td>输入后又改回原值再失焦</td><td>触发</td><td><strong>不触发</strong>（值没变）</td></tr></tbody></table><p>最后一行是 <code>change</code> 的准确含义：<strong>值确实发生变化时才触发。</strong> 所以在需要“用户改了就立刻处理”的地方用 <code>input</code>，需要“用户确定了再处理”的地方用 <code>change</code>。</p><h3 id="只做了前端校验就宣称-安全了" tabindex="-1">只做了前端校验就宣称“安全了” <a class="header-anchor" href="#只做了前端校验就宣称-安全了" aria-label="Permalink to &quot;只做了前端校验就宣称“安全了”&quot;">​</a></h3><p><strong>现象</strong>：你问它“这样校验够不够”，它回答“已经很完善了，可以防止非法数据提交”。</p><p><strong>原因</strong>：它判断“够不够”的依据是“校验规则覆盖了哪些情况”，而它看不到一个事实：<strong>用户可以绕过你的页面直接发请求。</strong></p><p><strong>怎么处理</strong>：记住这条边界 ——</p><blockquote><p><strong>前端校验挡的是手误，不挡恶意请求。真正的边界在服务端。</strong></p></blockquote><p>这不是说前端校验没用，而是说它解决的是<strong>体验问题</strong>：立刻告诉用户哪里填错了，不用等一次往返。它的价值在体验，不在安全。</p><p>所以判断规则该放哪，看这条：<strong>“如果这个校验被绕过，会不会造成实际损失？”</strong> 会，就必须在服务端也做一遍。比如“名额上限不能超过场地容量”“截止时间之后不能再报名”这两条，前端做是为了体验，后端做才是真的挡住了。</p><p>这个判断在<a href="/frontend-engineering-course/unit09/ai-collaboration.html">单元 9</a>和<a href="/frontend-engineering-course/unit10/ai-collaboration.html">单元 10</a>里还会接着用。</p><h3 id="忘记清理副作用" tabindex="-1">忘记清理副作用 <a class="header-anchor" href="#忘记清理副作用" aria-label="Permalink to &quot;忘记清理副作用&quot;">​</a></h3><p><strong>现象</strong>：它在 <code>onMounted</code> 里注册了 <code>window.addEventListener</code> 或 <code>setInterval</code>，但没写对应的 <code>onUnmounted</code>。或者在 <code>onUnmounted</code> 里写了，但清的不是同一个东西。</p><p><strong>原因</strong>：它的注意力集中在“让功能跑起来”，<code>onMounted</code> 是功能，<code>onUnmounted</code> 是收尾。收尾这件事在生成代码时不显眼。</p><p><strong>怎么处理</strong>：现象很好辨认 —— <strong>在页面之间来回切换几次，如果日志越来越多、定时器越来越多、请求越来越密，就是没清。</strong></p><table tabindex="0"><thead><tr><th>副作用</th><th>在哪清</th><th>清的是什么</th></tr></thead><tbody><tr><td><code>setInterval</code></td><td><code>onUnmounted</code></td><td>用注册时拿到的 id 调 <code>clearInterval</code></td></tr><tr><td><code>window.addEventListener</code></td><td><code>onUnmounted</code></td><td>同一个函数引用 + 同样的事件名</td></tr><tr><td>事件监听绑在元素上</td><td><code>onUnmounted</code></td><td>同上</td></tr><tr><td>请求</td><td>视情况</td><td>用取消令牌，或用一个标志位丢弃过期的响应</td></tr></tbody></table><p>第三条有个常见坑：<code>removeEventListener</code> 必须传<strong>同一个函数引用</strong>。写成 <code>removeEventListener(&#39;resize&#39;, () =&gt; {...})</code> 是无效的 —— 那是一个新函数，跟注册的那个不是同一个。这个问题不报错，只是悄悄没起作用。</p><details class="details custom-block"><summary>还有一类错误：请求发出去了，不管组件还在不在</summary><p><strong>现象</strong>：它在 <code>onMounted</code> 里发请求，回调里直接给状态赋值。你在请求还没回来时切到了别的页面，控制台开始报错，或者数据被写进了一个已经不在的组件。</p><p><strong>原因</strong>：它默认请求一定会成功、而且用户一定会等。这两件事在真实环境里都不成立。</p><p><strong>怎么处理</strong>：区分两种后果，因为它们要分开解决。</p><p><strong>后果一：竞态</strong> —— 连续两次请求，先发的后回来，把新结果覆盖了。典型场景是搜索框边输边查。解决办法是给请求编号，只认最后一次：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> seq </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> search</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">keyword</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> current</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ++</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">seq</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> data</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fetchList</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(keyword)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (current </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> seq) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 已经有更新的请求发出，这次的结果丢弃</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  list.value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> data</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>后果二：卸载后写状态</strong> —— 组件已经不在，回调还在给它赋值。解决办法是在卸载钩子里立一个标志位：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> alive </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">onUnmounted</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { alive </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">onMounted</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> data</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fetchList</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">alive) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  list.value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> data</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>判断用哪一种：<strong>看这个请求会不会被连续触发。</strong> 搜索、筛选、分页这类会连续触发的，要处理竞态；只在进入页面时发一次的，立标志位就够。</p></details><h2 id="怎么验收-ai-的产出" tabindex="-1">怎么验收 AI 的产出 <a class="header-anchor" href="#怎么验收-ai-的产出" aria-label="Permalink to &quot;怎么验收 AI 的产出&quot;">​</a></h2><p>这一章的产出是表单相关的代码。验收时按“不顺利的路径 → 副作用 → 修饰符边界”的顺序过：</p><ul><li>[ ] 校验规则写成了纯函数，没有依赖 Vue 的响应式 API</li><li>[ ] 每条规则你都能说出一个“什么输入会被误判”的场景</li><li>[ ] 校验失败的提示能落到具体字段，不是一条笼统的错误</li><li>[ ] 提交时做了防重复：按钮置灰、提交中标志、请求层面至少有一层</li><li>[ ] 代码里每一处副作用，都有对应的清理，且清的是同一个东西</li><li>[ ] 用了 <code>.lazy</code> 的地方，确认没有别处依赖实时值</li><li>[ ] 用了 <code>.number</code> 的地方，校验的是值本身而不只是类型</li><li>[ ] 你没有因为 AI 说“校验已经很完善”就跳过后端的校验设计</li></ul><p>前四条对应“不顺利的路径写全了没”，中间两条对应“有没有留下垃圾”，最后两条对应两个边界。<strong>这八条过完，这个表单才算能交出去。</strong></p><h2 id="练习" tabindex="-1">练习 <a class="header-anchor" href="#练习" aria-label="Permalink to &quot;练习&quot;">​</a></h2><h3 id="给一个带实时校验的表单-故意留一个没清理的定时器" tabindex="-1">给一个带实时校验的表单，故意留一个没清理的定时器 <a class="header-anchor" href="#给一个带实时校验的表单-故意留一个没清理的定时器" aria-label="Permalink to &quot;给一个带实时校验的表单，故意留一个没清理的定时器&quot;">​</a></h3><p><strong>任务</strong>：写一个带实时校验的表单（比如“创建活动”），<strong>故意在组件里留一个没清理的定时器或事件监听</strong>，然后让 AI 找出来。找到之后自己改对，并说明为什么必须清。</p><p><strong>要求</strong>：记录里必须包含这四项：</p><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>故意埋的副作用</td><td>写清埋的是什么、埋在哪一段</td></tr><tr><td>不清理时的现象</td><td>写清怎么观察到的（切页面几次？看什么？）</td></tr><tr><td>AI 有没有找出来</td><td>找出来了就粘它的定位过程；没找出来就写你换了什么问法</td></tr><tr><td>改完的验证</td><td>写清改完之后同一个观察办法看到了什么不同</td></tr></tbody></table><details class="details custom-block"><summary>验收标准与参考思路</summary><p><strong>为什么是“故意埋”</strong>：等副作用问题自己暴露出来，通常要等到项目快交付的时候，而且现象是“页面越用越卡”这种没法定位的描述。主动埋一个，你知道它在哪，就能专心观察“不清理会表现成什么样”—— 这个认识比知道“要清理”有用得多。</p><p><strong>思路提示</strong>：</p><ul><li>埋什么建议挑这两个之一：<code>setInterval</code> 每秒更新一个“剩余时间”，或者给 <code>window</code> 加一个 <code>resize</code> 监听。这两个的现象都容易观察。</li><li>观察办法：在页面之间来回切 5 次，如果定时器没清，控制台的输出会变成 5 倍频。<strong>用输出次数来判断，比用眼睛猜准确。</strong></li><li>如果 AI 没找出来，<strong>先换问法再下结论</strong>。用第 2 个提示词模板（要求“逐个列出、落到清理位置”），比问“有没有内存泄漏”有效得多。记录下两种问法的差别，这本身就是这一节要教的东西。</li><li>顺手试一下那个“同一个函数引用”的坑：故意写成 <code>removeEventListener(&#39;resize&#39;, () =&gt; {})</code>，看 AI 能不能指出来。<strong>这是这一章最隐蔽的一个坑，因为它不报错。</strong></li></ul><p><strong>不合格的写法</strong>：</p><blockquote><p>让 AI 检查了一下，它说没有内存泄漏，我就没再管。</p></blockquote><p>AI 说“没有”的时候，你要看它是怎么得出结论的。它逐行对照过每个副作用的注册与清理位置吗？还是只看了代码“像不像有清理”？</p><p><strong>合格的写法</strong>：</p><blockquote><p>我埋了一个 <code>setInterval</code>，每秒更新“报名倒计时”，写在 <code>onMounted</code> 里，没有 <code>onUnmounted</code>。 观察办法：在活动列表和详情页之间切换 5 次，控制台每秒输出 5 行 —— 说明 5 个定时器同时在跑。 第一次问 AI“有没有内存泄漏”，它回答“代码结构合理，未发现明显问题”，没找出问题。 换成第 2 个提示词模板后，它列出的副作用表里，<code>setInterval</code> 那一行“在哪清理的”是空的， 这才定位到。说明<strong>笼统地问它只会给笼统的回答。</strong> 加上 <code>onUnmounted</code> 清理之后，同样的切换操作只输出 1 行/秒。 另外我试了 <code>removeEventListener(&#39;resize&#39;, () =&gt; {})</code>，它没指出来 —— 这个坑得靠自己记。</p></blockquote><p>差别在于：后者不但找到了问题，还发现了<strong>自己的提问方式才是问题的一部分</strong>。这一条经验在后面的单元会一直用到。</p></details><hr><p>上一节：<a href="/frontend-engineering-course/unit06/06-case-markdown.html">案例 05 · Markdown 编辑器</a> · 课后练习：<a href="/frontend-engineering-course/unit06/practice.html">单元 6 课后练习</a></p>`,64)])])}const k=t(i,[["render",l]]);export{g as __pageData,k as default};
